mapper.select:
SELECT COUNT(*) FROM `order`
WHERE store_id = #{storeId} AND date = #{date} AND meal_type = #{mealType}
  AND status IN (1, 2)

SELECT status AS status, COUNT(*) AS cnt FROM `order`
WHERE store_id = #{storeId}

    AND status = #{status}


    AND meal_type = #{mealType}


    AND order_source = #{orderSource}


    AND date >= #{startDate}


    AND date <= #{endDate}


    AND (order_no LIKE CONCAT('%', #{keyword}, '%')
         OR employee_name LIKE CONCAT('%', #{keyword}, '%')
         OR card_no LIKE CONCAT('%', #{keyword}, '%'))

GROUP BY status
